                if (လုပ်ဆောင်ချက်.အမည်.equals("<init>")) continue;
                if ((လုပ်ဆောင်ချက်.ဝင်သုံးအချက် & 8) == 0 || (လုပ်ဆောင်ချက်.ဝင်သုံးအချက် & (0x20 | 0x400)) != 0) throw new ဘာသာပြန်ဆိုမှုအမှား("တည်ငြိမ်တန်ဖိုး 비동기화 함수만 ထောက်ပံ့မှုတန်ဖိုး");
                new နည်းလမ်းအညွှန်း(လုပ်ဆောင်ချက်.ဖော်ပြချက်);
                if (လုပ်ဆောင်နည်းများ.put(new နည်းလမ်းကိုးကားချက်(ဒေတာ.အမည်, လုပ်ဆောင်ချက်.အမည်, လုပ်ဆောင်ချက်.ဖော်ပြချက်), လုပ်ဆောင်ချက်) != null) throw new ဘာသာပြန်ဆိုမှုအမှား("중복 လုပ်ဆောင်ချက်");
