        List<String> အထွက် = new ArrayList<>(); အထွက်.add(လုပ်ဆောင်နည်းပုံစံ(လုပ်ဆောင်ချက်) + " {");
        အထွက်.add("word s[" + Math.max(ထပ်ဆင့်အစုအနက်, 1) + "], l[" + Math.max(ဒေသတွင်းကိန်းရှင်အရေအတွက်, 1) + "] = {0}, a,b,c,d; size_t sp = 0;");
