                အသစ်အမည် = အမည်ဇယား.getOrDefault(အမည်, အမည်);
                if (အမည်.matches("a[0-9]+")) အသစ်အမည် = "အချက်များ" + အမည်.substring(1);
                if (အမည်.matches("b[0-9]+")) အသစ်အမည် = "အခွဲ" + အမည်.substring(1);
